from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
leefftt_DDRRIIVVEE_____ = Motor(Port.E, Direction.COUNTERCLOCKWISE)
wat54sacvyujyuc_yu_crftrx = Motor(Port.D, Direction.CLOCKWISE)
drive_base_2 = DriveBase(leefftt_DDRRIIVVEE_____, wat54sacvyujyuc_yu_crftrx, 56, 114)

def run_blue_mission(drive_base, left_drive, right_drive, left_attachment, right_attachment):
    drive_base.turn(100)
    drive_base.straight(590)
    drive_base.settings(turn_rate=60)
    drive_base.turn(-75)
    drive_base.straight(30)
    drive_base.straight(0)
    drive_base.settings(turn_rate=150)
    drive_base.turn(-60)
    drive_base.turn(40)
    drive_base.straight(10)
    drive_base.turn(-40)
    drive_base.turn(30)
    drive_base.straight(-30)
    drive_base.turn(60)
    drive_base.straight(-300)
